node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get current reservation to build refund payment history
const row = db.prepare(\"SELECT * FROM flight_bookings WHERE booking_id = 'A58410'\").get();
const paymentHistory = JSON.parse(row.payment_history_json);

// Add refund entries (negative amounts)
const refunds = paymentHistory.map(p => ({ payment_id: p.payment_id, amount: -p.amount }));
const updatedHistory = [...paymentHistory, ...refunds];

// Update reservation status to cancelled and add refund to payment history
db.prepare(\"UPDATE flight_bookings SET status = 'cancelled', payment_history_json = ? WHERE booking_id = 'A58410'\").run(JSON.stringify(updatedHistory));

// Verify
const updated = db.prepare(\"SELECT booking_id, status, payment_history_json FROM flight_bookings WHERE booking_id = 'A58410'\").get();
console.log(JSON.stringify(updated, null, 2));

db.close();
"
